import * as React from "react";
import { cva, type VariantProps } from "class-variance-authority";

import { cn } from "@/lib/utils";
import { Label } from "./label";

/**
 * figma: Field page — FieldLabel (State = Default | Destructive | Disabled),
 * FieldDescription (Alignment = Left | Right) and the Field wrapper.
 *
 * `Field` is the layout primitive every form control in the library sits in;
 * orientation mirrors the Figma "Type" property.
 */
const fieldVariants = cva("group/field flex w-full data-[invalid=true]:text-text-destructive", {
  variants: {
    orientation: {
      vertical: "flex-col gap-2 [&>*]:w-full",
      horizontal: "flex-row items-center gap-2 [&>[data-slot=field-label]]:flex-auto",
      responsive:
        "flex-col gap-2 @md/field-group:flex-row @md/field-group:items-center @md/field-group:gap-2",
    },
  },
  defaultVariants: { orientation: "vertical" },
});

function Field({
  className,
  orientation,
  ...props
}: React.ComponentProps<"div"> & VariantProps<typeof fieldVariants>) {
  return (
    <div
      role="group"
      data-slot="field"
      data-orientation={orientation ?? "vertical"}
      className={cn(fieldVariants({ orientation }), className)}
      {...props}
    />
  );
}

function FieldGroup({ className, ...props }: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="field-group"
      className={cn("@container/field-group flex w-full flex-col gap-6", className)}
      {...props}
    />
  );
}

function FieldSet({ className, ...props }: React.ComponentProps<"fieldset">) {
  return (
    <fieldset
      data-slot="field-set"
      className={cn("flex flex-col gap-4 disabled:opacity-50", className)}
      {...props}
    />
  );
}

function FieldLegend({
  className,
  variant = "legend",
  ...props
}: React.ComponentProps<"legend"> & { variant?: "legend" | "label" }) {
  return (
    <legend
      data-slot="field-legend"
      data-variant={variant}
      className={cn(
        "mb-2 font-medium",
        variant === "legend" ? "text-base" : "text-sm",
        className
      )}
      {...props}
    />
  );
}

function FieldLabel({ className, ...props }: React.ComponentProps<typeof Label>) {
  return (
    <Label
      data-slot="field-label"
      className={cn(
        "group/field-label peer/field-label flex w-fit gap-2 leading-snug",
        "group-data-[invalid=true]/field:text-text-destructive",
        "group-data-[disabled=true]/field:opacity-50",
        className
      )}
      {...props}
    />
  );
}

/**
 * Wraps the control's label and helper text so they stay aligned when a Field
 * is horizontal or responsive.
 */
function FieldContent({ className, ...props }: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="field-content"
      className={cn("flex flex-1 flex-col gap-1 leading-snug", className)}
      {...props}
    />
  );
}

function FieldDescription({ className, ...props }: React.ComponentProps<"p">) {
  return (
    <p
      data-slot="field-description"
      className={cn(
        "text-sm leading-normal font-normal text-muted-foreground",
        "group-data-[disabled=true]/field:opacity-50",
        className
      )}
      {...props}
    />
  );
}

function FieldError({
  className,
  children,
  errors,
  ...props
}: React.ComponentProps<"div"> & { errors?: Array<{ message?: string } | undefined> }) {
  const content =
    children ??
    (errors?.length === 1
      ? errors[0]?.message
      : errors?.length
        ? (
            <ul className="ml-4 flex list-disc flex-col gap-1">
              {errors.map((e, i) => (e?.message ? <li key={i}>{e.message}</li> : null))}
            </ul>
          )
        : null);
  if (!content) return null;
  return (
    <div
      role="alert"
      data-slot="field-error"
      className={cn("text-sm font-normal text-text-destructive", className)}
      {...props}
    >
      {content}
    </div>
  );
}

function FieldSeparator({ className, children, ...props }: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="field-separator"
      data-content={!!children}
      className={cn("relative -my-2 h-5 text-sm", className)}
      {...props}
    >
      <div className="absolute inset-0 top-1/2 h-px bg-border" />
      {children ? (
        <span className="relative mx-auto block w-fit bg-background px-2 text-muted-foreground">
          {children}
        </span>
      ) : null}
    </div>
  );
}

export {
  Field,
  FieldGroup,
  FieldSet,
  FieldLegend,
  FieldLabel,
  FieldContent,
  FieldDescription,
  FieldError,
  FieldSeparator,
  fieldVariants,
};
